from z3 import *

n = 20
min_girth = 7
min_edges = 37
max_colors = 4

def edge_key(i, j):
    return (min(i,j), max(i,j))

# Create boolean variables for each possible edge
edges = {}
for i in range(n):
    for j in range(i+1, n):
        edges[(i,j)] = Bool(f"e_{i}_{j}")

s = Solver()

# Constraint: at least 37 edges
edge_vars = [edges[(i,j)] for i in range(n) for j in range(i+1, n)]
s.add(Sum([If(e, 1, 0) for e in edge_vars]) >= min_edges)

# Constraint: no cycles of length 3, 4, 5, or 6
# No triangles (cycles of length 3)
for i in range(n):
    for j in range(i+1, n):
        for k in range(j+1, n):
            s.add(Not(And(edges[(i,j)], edges[(j,k)], edges[(i,k)])))

# No cycles of length 4
for i in range(n):
    for j in range(i+1, n):
        for k in range(j+1, n):
            for l in range(k+1, n):
                # All possible 4-cycles among 4 vertices
                s.add(Not(And(edges[(i,j)], edges[(j,k)], edges[(k,l)], edges[(i,l)])))
                s.add(Not(And(edges[(i,j)], edges[(j,l)], edges[(k,l)], edges[(i,k)])))
                s.add(Not(And(edges[(i,k)], edges[(j,k)], edges[(j,l)], edges[(i,l)])))

print("Added triangle and 4-cycle constraints")
print(f"Number of constraints so far: {len(s.assertions())}")

# No cycles of length 5
for i in range(n):
    for j in range(i+1, n):
        for k in range(j+1, n):
            for l in range(k+1, n):
                for m in range(l+1, n):
                    # All possible 5-cycles among 5 vertices
                    # A 5-cycle is a permutation of 5 vertices forming a cycle
                    # We need to check all distinct 5-cycles
                    vertices = [i, j, k, l, m]
                    # Generate all 5-cycles (up to rotation and reflection)
                    # Fix first vertex, then permute the rest
                    from itertools import permutations
                    seen = set()
                    for perm in permutations(vertices[1:]):
                        cycle = [vertices[0]] + list(perm)
                        # Normalize: start from smallest, go in direction of smaller second
                        min_idx = cycle.index(min(cycle))
                        cycle = cycle[min_idx:] + cycle[:min_idx]
                        if cycle[1] > cycle[-1]:
                            cycle = [cycle[0]] + cycle[1:][::-1]
                        key = tuple(cycle)
                        if key not in seen:
                            seen.add(key)
                            e1 = edge_key(cycle[0], cycle[1])
                            e2 = edge_key(cycle[1], cycle[2])
                            e3 = edge_key(cycle[2], cycle[3])
                            e4 = edge_key(cycle[3], cycle[4])
                            e5 = edge_key(cycle[4], cycle[0])
                            s.add(Not(And(edges[e1], edges[e2], edges[e3], edges[e4], edges[e5])))

print("Added 5-cycle constraints")
print(f"Number of constraints so far: {len(s.assertions())}")

# No cycles of length 6
for i in range(n):
    for j in range(i+1, n):
        for k in range(j+1, n):
            for l in range(k+1, n):
                for m in range(l+1, n):
                    for p in range(m+1, n):
                        vertices = [i, j, k, l, m, p]
                        from itertools import permutations
                        seen = set()
                        for perm in permutations(vertices[1:]):
                            cycle = [vertices[0]] + list(perm)
                            min_idx = cycle.index(min(cycle))
                            cycle = cycle[min_idx:] + cycle[:min_idx]
                            if cycle[1] > cycle[-1]:
                                cycle = [cycle[0]] + cycle[1:][::-1]
                            key = tuple(cycle)
                            if key not in seen:
                                seen.add(key)
                                e1 = edge_key(cycle[0], cycle[1])
                                e2 = edge_key(cycle[1], cycle[2])
                                e3 = edge_key(cycle[2], cycle[3])
                                e4 = edge_key(cycle[3], cycle[4])
                                e5 = edge_key(cycle[4], cycle[5])
                                e6 = edge_key(cycle[5], cycle[0])
                                s.add(Not(And(edges[e1], edges[e2], edges[e3], edges[e4], edges[e5], edges[e6])))

print("Added 6-cycle constraints")
print(f"Number of constraints so far: {len(s.assertions())}")

# 4-colorability constraint
color_vars = [[Int(f"c_{i}_{j}") for j in range(max_colors)] for i in range(n)]
for i in range(n):
    # Each vertex has exactly one color
    s.add(Sum(color_vars[i]) == 1)
    for j in range(max_colors):
        s.add(Or(color_vars[i][j] == 0, color_vars[i][j] == 1))

# Adjacent vertices must have different colors
for i in range(n):
    for j in range(i+1, n):
        for c in range(max_colors):
            # If edge (i,j) exists, then vertices i and j can't both have color c
            s.add(Not(And(edges[(i,j)], color_vars[i][c] == 1, color_vars[j][c] == 1)))

print("Added coloring constraints")
print(f"Total constraints: {len(s.assertions())}")

print("Solving...")
result = s.check()
print(f"Result: {result}")

if result == sat:
    m = s.model()
    graph_edges = []
    for i in range(n):
        for j in range(i+1, n):
            if m.evaluate(edges[(i,j)]):
                graph_edges.append((i, j))
    print(f"Found graph with {len(graph_edges)} edges")
    print(f"Edges: {graph_edges}")

    # Verify
    colors = {}
    for i in range(n):
        for c in range(max_colors):
            if m.evaluate(color_vars[i][c]) == 1:
                colors[i] = c
                break
    print(f"Colors: {colors}")
